package ro.leo.visual;
import ro.leo.i18n.L;
import android.app.*;import android.content.*;import android.database.Cursor;import android.os.*;import android.provider.*;import android.text.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;

/** On-demand, bounded local search. No persistent index or background service. */
public final class GlobalSearchActivity extends LeoActivity {
 static final class Hit {final String label;final Intent intent;Hit(String s,Intent i){label=s;intent=i;}}
 static final String[] SCOPES={"Toate","Aplicații","Contacte","Setări","Muzică","Altele"};
 private int scope;
 private TextView summary;private EditText query;private ListView results;private final Handler handler=new Handler();private volatile int generation;
 private final Runnable search=new Runnable(){public void run(){find();}};
 static boolean matches(String value,String query){return (query.matches("[0-9]+")&&ContactKeys.matches(value==null?"":value,"",query))||fold(value).contains(fold(query));}
 private static String fold(String s){return java.text.Normalizer.normalize(s==null?"":s,java.text.Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase(Locale.ROOT);}
 protected void onCreate(Bundle b){super.onCreate(b);begin(L.t("Caută în Leo"));query=new EditText(this);query.setTextSize(19*Appearance.textScale(this));query.setSingleLine(true);query.setTextColor(android.graphics.Color.WHITE);query.setHintTextColor(0xffaaaaaa);query.setHint(L.t("Aplicații, contacte, SMS, calendar, fișiere"));query.setInputType(InputType.TYPE_CLASS_TEXT);query.setFilters(new InputFilter[]{new InputFilter.LengthFilter(80)});root.addView(query);summary=text(L.t("Se caută…"),12);root.addView(summary);results=new ListView(this);results.setFocusableInTouchMode(true);root.addView(results,new LinearLayout.LayoutParams(-1,0,1));footer(L.t("Categorii"),L.t("Rezultate ↓"),L.t("Șterge"));left=new Runnable(){public void run(){options(L.t("Caută în Leo"),L.array(SCOPES),new Choice(){public void pick(int at){scope=at;find();query.requestFocus();}});}};query.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){++generation;handler.removeCallbacks(search);handler.postDelayed(search,250);}public void afterTextChanged(Editable e){}});scope=b==null?0:Math.max(0,Math.min(SCOPES.length-1,b.getInt("scope",0)));query.setText(b==null?getIntent().getStringExtra("query"):b.getString("query",""));query.setOnKeyListener(new View.OnKeyListener(){public boolean onKey(View v,int k,KeyEvent e){if(k==KeyEvent.KEYCODE_DPAD_DOWN&&e.getAction()==0){results.requestFocus();return true;}return false;}});find();query.requestFocus();}
 protected void onSaveInstanceState(Bundle b){b.putInt("scope",scope);b.putString("query",query.getText().toString());super.onSaveInstanceState(b);}
 protected void onResume(){super.onResume();if(query!=null)find();}
 protected void onPause(){handler.removeCallbacks(search);++generation;super.onPause();}protected void onDestroy(){handler.removeCallbacksAndMessages(null);super.onDestroy();}
 private void find(){summary.setText(L.t("Se caută…"));results.setEnabled(false);final String term=query.getText().toString().trim();final int token=++generation,chosen=scope;worker.execute(new Runnable(){public void run(){if(token!=generation)return;final ArrayList<Hit> hits=collect(GlobalSearchActivity.this,term,chosen);for(int i=hits.size()-1;i>=0;i--)if(!inScope(hits.get(i),chosen))hits.remove(i);ui(new Runnable(){public void run(){if(token!=generation||isFinishing())return;summary.setText(L.t(SCOPES[chosen])+" · "+hits.size());results.setEnabled(true);ArrayList<String> labels=new ArrayList<String>();for(Hit h:hits)labels.add(h.label);if(labels.isEmpty())labels.add(term.isEmpty()?L.t("Scrie pentru a căuta local"):L.t("Niciun rezultat · limite locale"));results.setAdapter(new ArrayAdapter<String>(GlobalSearchActivity.this,android.R.layout.simple_list_item_1,labels){public View getView(int p,View v,android.view.ViewGroup parent){TextView t=(TextView)super.getView(p,v,parent);t.setTextColor(android.graphics.Color.WHITE);t.setTextSize(16*Appearance.textScale(GlobalSearchActivity.this));return t;}});results.setOnItemClickListener(new AdapterView.OnItemClickListener(){public void onItemClick(AdapterView<?> a,View v,int i,long id){if(i<hits.size())try{startActivity(hits.get(i).intent);}catch(RuntimeException e){notice(L.t("Rezultat indisponibil"));}}});}});}});}
 static boolean inScope(Hit hit,int scope){if(scope==0)return true;String name=hit.intent.getComponent()==null?"":hit.intent.getComponent().getClassName();int type=name.endsWith("MainActivity")?1:name.endsWith("ContactsActivity")?2:name.endsWith("MediaActivity")?4:(hit.label.startsWith(L.t("Setare · "))||name.contains("SettingsActivity")||name.endsWith("SoundScheduleActivity")||name.endsWith("SetupWizardActivity"))?3:5;return type==scope;}
 static ArrayList<Hit> collect(Context c,String term){return collect(c,term,0);}
 static ArrayList<Hit> collect(Context c,String term,int scope){ArrayList<Hit> found=new ArrayList<Hit>();if(term.isEmpty())return found;
  for(int i=0;i<AppCatalog.NAMES.length&&found.size()<20;i++)if(matches(AppCatalog.NAMES[i],term))found.add(new Hit(L.t("Aplicație · ")+AppCatalog.NAMES[i],new Intent(c,MainActivity.class).putExtra("open_app",i).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP)));
  String[] settingNames=L.array(new String[]{"Wi-Fi","Bluetooth","Program sonor","Accesibilitate Leo","Configurare inițială","Setări Leo","Tastatură și text","Fundaluri și teme","SIM-uri și rețea mobilă"});
  Class<?>[] settingPages={ConnectivityActivity.class,ConnectivityActivity.class,SoundScheduleActivity.class,AccessibilitySettingsActivity.class,SetupWizardActivity.class,SettingsActivity.class,InputSettingsActivity.class,WallpaperActivity.class,MobileSettingsActivity.class};
  for(int i=0;i<settingNames.length;i++)if(matches(settingNames[i],term)){Intent intent=new Intent(c,settingPages[i]);if(i<2)intent.putExtra("kind",i==0?"wifi":"bluetooth");found.add(new Hit(L.t("Setare · ")+settingNames[i],intent));}
  if(scope==3)return found;
  try(Cursor rows=c.getContentResolver().query(ContactsContract.CommonDataKinds.Phone.CONTENT_URI,new String[]{"contact_id","display_name","data1"},null,null,"display_name COLLATE LOCALIZED ASC")){HashSet<Long> ids=new HashSet<Long>();int scanned=0,n=0;while(rows!=null&&rows.moveToNext()&&scanned++<2000&&n<20)if((matches(rows.getString(1),term)||matches(rows.getString(2),term))&&ids.add(rows.getLong(0))){found.add(new Hit(L.t("Contact · ")+rows.getString(1),new Intent(c,ContactsActivity.class).putExtra("contact_id",rows.getLong(0))));n++;}}catch(RuntimeException ignored){}
  try{File f=new File(c.getFilesDir(),"notes.json");if(BackupEngine.atomicExists(f)){JSONArray notes=new JSONArray(new String(BackupEngine.atomicBytes(f,1024*1024),"UTF-8"));int n=0;for(int i=0;i<notes.length()&&n<20;i++){JSONObject note=notes.getJSONObject(i);String body=note.getString("body");if(matches(body,term)){found.add(new Hit(L.t("Notiță · ")+body.replace('\n',' ').substring(0,Math.min(body.length(),60)),new Intent(c,NotesActivity.class).putExtra("note_id",note.getString("id"))));n++;}}}}catch(Exception ignored){}
  try(Cursor rows=c.getContentResolver().query(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,new String[]{"_id","title","artist"},null,null,"title COLLATE NOCASE ASC")){int scanned=0,n=0;while(rows!=null&&rows.moveToNext()&&scanned++<2000&&n<20)if(matches(rows.getString(1),term)||matches(rows.getString(2),term)){found.add(new Hit(L.t("Muzică · ")+rows.getString(1),new Intent(c,MediaActivity.class).setData(ContentUris.withAppendedId(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,rows.getLong(0)))));n++;}}catch(RuntimeException ignored){}ExtendedSearch.append(c,term,found);return found;
 }
}
